DECLARE
  l_failures      NUMBER := 0;
  l_match_dept    employees.department_id%TYPE;
  l_no_match_dept employees.department_id%TYPE;
  l_expected      NUMBER;
  l_actual        NUMBER;
  l_check_count   NUMBER;

  PROCEDURE check_result(
    p_name     IN VARCHAR2,
    p_expected IN NUMBER,
    p_actual   IN NUMBER
  ) IS
  BEGIN
    IF p_expected = p_actual THEN
      DBMS_OUTPUT.PUT_LINE(
        'PASS: ' || p_name ||
        ' expected=' || p_expected ||
        ' actual=' || p_actual
      );
    ELSE
      l_failures := l_failures + 1;
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: ' || p_name ||
        ' expected=' || p_expected ||
        ' actual=' || p_actual
      );
    END IF;
  END check_result;

  PROCEDURE fail_setup(
    p_name   IN VARCHAR2,
    p_reason IN VARCHAR2
  ) IS
  BEGIN
    l_failures := l_failures + 1;
    DBMS_OUTPUT.PUT_LINE('FAIL: ' || p_name || ' - ' || p_reason);
  END fail_setup;
BEGIN
  SAVEPOINT test_headcount;

  -- Check 1: a department_id that matches at least one row.
  BEGIN
    SELECT MIN(department_id)
      INTO l_match_dept
      FROM employees
     WHERE department_id IS NOT NULL;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      l_match_dept := NULL;
  END;

  IF l_match_dept IS NULL THEN
    fail_setup(
      'matching department_id',
      'no non-NULL department_id with rows was found in employees'
    );
  ELSE
    SELECT COUNT(*)
      INTO l_expected
      FROM employees
     WHERE department_id = l_match_dept;

    l_actual := HARNESS_APP.headcount(l_match_dept);

    check_result(
      'matching department_id',
      l_expected,
      l_actual
    );
  END IF;

  -- Check 2: a department_id that matches no row.
  BEGIN
    SELECT MIN(department_id) - 1
      INTO l_no_match_dept
      FROM employees
     WHERE department_id IS NOT NULL;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      l_no_match_dept := NULL;
  END;

  IF l_no_match_dept IS NULL THEN
    fail_setup(
      'non-matching department_id',
      'no non-NULL department_id was found to derive a non-matching value from'
    );
  ELSE
    SELECT COUNT(*)
      INTO l_check_count
      FROM employees
     WHERE department_id = l_no_match_dept;

    IF l_check_count <> 0 THEN
      fail_setup(
        'non-matching department_id',
        'derived value ' || l_no_match_dept || ' unexpectedly matches rows'
      );
    ELSE
      l_expected := 0;
      l_actual   := HARNESS_APP.headcount(l_no_match_dept);

      check_result(
        'non-matching department_id',
        l_expected,
        l_actual
      );
    END IF;
  END IF;

  -- Check 3: NULL argument.
  -- The function compares department_id = p_department_id.
  -- Equality with NULL matches no rows, so the expected result is 0.
  l_expected := 0;
  l_actual   := HARNESS_APP.headcount(NULL);

  check_result(
    'NULL department_id',
    l_expected,
    l_actual
  );

  DBMS_OUTPUT.PUT_LINE('Summary: failures=' || l_failures);

  ROLLBACK TO test_headcount;

  IF l_failures <> 0 THEN
    RAISE_APPLICATION_ERROR(
      -20999,
      'headcount test block failed with ' || l_failures || ' failure(s)'
    );
  END IF;
EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('Unexpected error: ' || SQLERRM);
    ROLLBACK TO test_headcount;
    RAISE;
END;
```

The block checks three cases:

1. A `department_id` that matches at least one row in `employees`. It finds a non-NULL `department_id`, computes the expected count independently with a separate `COUNT(*)` query, calls `HARNESS_APP.headcount`, and compares the result. If no such department exists, it reports `FAIL` rather than silently skipping the check.

2. A `department_id` that matches no row. It derives a candidate value from the minimum non-NULL `department_id`, confirms with `COUNT(*)` that no rows match it, then calls `HARNESS_APP.headcount` and expects `0`. If no suitable non-matching value can be found or confirmed, it reports `FAIL`.

3. A `NULL` argument. Because the function uses `department_id = p_department_id`, a `NULL` argument matches no rows, so the expected result is `0`, not a count of rows where `department_id IS NULL`.

The block starts with a savepoint and rolls back to it at the end, so it does not commit. If an unexpected exception occurs, it prints the error, rolls back to the savepoint, and re-raises. I have not run this block.

